<?php
require_once __DIR__ . '/_bootstrap.php';
$stats=[['label'=>'Total shipments','value'=>logisticsScalar('SELECT COUNT(*) FROM shipments')],['label'=>'In transit','value'=>logisticsScalar("SELECT COUNT(*) FROM shipments WHERE status='in_transit'")],['label'=>'Delivered','value'=>logisticsScalar("SELECT COUNT(*) FROM shipments WHERE status='delivered'")],['label'=>'Exceptions','value'=>logisticsScalar("SELECT COUNT(*) FROM shipments WHERE status IN ('exception','delayed')")]];
$recent=logisticsRows('SELECT * FROM shipments ORDER BY created_at DESC LIMIT 8');
logisticsPage('Control tower','dashboard.php'); ?>
<section class="lx-kpis"><?php foreach($stats as $s): ?><article class="lx-kpi"><span><?=e($s['label'])?></span><strong><?=e(number_format((int)$s['value']))?></strong></article><?php endforeach; ?></section>
<div class="lx-grid"><section class="lx-card"><h2>Shipment queue <a class="lx-btn" style="float:right;padding:7px 11px;font-size:12px" href="shipments.php">View all</a></h2><?php if(!$recent): ?><div class="lx-empty">No shipments are available yet. New orders will appear here.</div><?php else: ?><table class="lx-table"><thead><tr><th>Tracking</th><th>Route</th><th>Status</th><th>Updated</th></tr></thead><tbody><?php foreach($recent as $r): ?><tr><td><a href="shipment-details.php?id=<?=e($r['id']??'')?>"><?=e(logisticsValue($r,['tracking_number','tracking_code','reference']))?></a></td><td><?=e(logisticsValue($r,['destination','delivery_address','city']))?></td><td><span class="lx-badge"><?=e(logisticsStatus(logisticsValue($r,['status'],'pending')))?></span></td><td><?=e(logisticsValue($r,['updated_at','created_at']))?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></section><section class="lx-card"><h2>Operator brief</h2><p class="lx-eyebrow">TODAY'S FOCUS</p><p>Monitor handoffs, resolve delivery exceptions and keep buyers informed from one workspace.</p><div class="lx-actions"><a class="lx-btn gold" href="tracking.php">Track a shipment</a></div></section></div>
<?php logisticsEnd(); ?>
